import React, { useState, useEffect } from 'react';
import Plot from 'react-plotly.js';



 
// データをロードする関数
const loadCompanies = async (dataPath) => {
  try {
    const response = await fetch(dataPath);
    const text = await response.text();
    return text.split("\n").filter((line) => line.trim() !== "");
  } catch (error) {
    console.error("データの読み込みエラー:", error);
    return [];
  }
};

const toList = async (dataPath) => {
  try {
    const response = await fetch(dataPath);
    const text = await response.text();
    const lines = text.split("\n").filter(line => line.trim() !== "");

    const alpha_li = lines.map(line => parseFloat(line.split(",")[0]));
    const beta_li = lines.map(line => parseFloat(line.split(",")[1]));

    return { alpha_li, beta_li };
  } catch (error) {
    console.error("データの読み込みエラー:", error);
    return { alpha_li: [], beta_li: [] };
  }
};

const PlotPersonComp = ({ update, visualType, topic, company, onRendered }) => {
const IdtoTopic = {"2":"コンクリート構造","3":"地盤改良","1":"トンネル掘削",
  "0":"免震構造","9":"管理システム","6":"廃棄物処理","8":"建築パネル",
  "7":"空調システム","11":"掘削装置","12":"基礎構造","31":"配管搬送",
  "10":"建築設計","5":"トンネル測量","13":"電力管理","16":"屋根構造",
  "14":"構造損傷","24":"電磁波シールド","19":"天井構造","23":"音響検査",
  "15":"照明システム","17":"壁面緑化"};

const colormap = {"コンクリート構造":'rgb(229, 134, 6)', "地盤改良":'rgb(93, 105, 177)', "トンネル掘削":'rgb(82, 188, 163)',
          "免震構造":'rgb(153, 201, 69)', "管理システム":'rgb(204, 97, 176)', "廃棄物処理":'rgb(36, 121, 108)', 
          "建築パネル":'rgb(218, 165, 27)',"空調システム":'rgb(47, 138, 196)', "掘削装置":'rgb(118, 78, 159)', 
          "照明システム":'rgb(255, 127, 14)', "壁面緑化":'rgb(153, 153, 153)',"配管搬送":'rgb(255, 127, 14)'
        };

        
  const arrow_color = ['#E24E42', '#E9B000', '#EB6E80', '#9B7EDE', '#63D2FF'];

  const [preparedData, setPreparedData] = useState(null);
  const [figData, setFigData] = useState([]);
  const [annotations, setAnnotations] = useState([]);
  const [title, setTitle] = useState("企業の立ち位置");
  const [authorData, setAuthorData] = useState({});


  useEffect(() => {
    const prepareData = async () => {
      try {
        const allPromises = (topic || ["default_topic"]).map(async (target_id) => {
            console.log("topic",target_id)
          const columnPath = `${process.env.PUBLIC_URL}/data/visualize_data/topic${target_id}/span=3/setting/company.txt`;
          const companies = await loadCompanies(columnPath);

          const companyDict = companies.reduce((acc, value, idx) => {
            acc[value] = idx;
            return acc;
          }, {});

          const newSearchList = Array.isArray(company) ? company : [company];
          const filteredSearchList = newSearchList.filter(value => value in companyDict);

          const node_alpha = Array.from({ length: filteredSearchList.length }, () => Array(5).fill(0));
          const node_beta = Array.from({ length: filteredSearchList.length }, () => Array(5).fill(0));

          const promises = Array.from({ length: 5 }, (_, j) => j ).map(async (p) => {
            const parameterPath = `${process.env.PUBLIC_URL}/data/visualize_data/topic${target_id}/span=3/persona/test_optimize_${p+1}.txt`;
            const { alpha_li, beta_li } = await toList(parameterPath);

            filteredSearchList.forEach((k, j) => {
              const idx = companies.indexOf(k);
              node_alpha[j][p] = alpha_li[idx];
              node_beta[j][p] = beta_li[idx];
            });
          });

          await Promise.all(promises);

          return { node_alpha, node_beta, filteredSearchList };
        });

        const results = await Promise.all(allPromises);

        const combinedAlpha = results.flatMap(result => result.node_alpha);
        const combinedBeta = results.flatMap(result => result.node_beta);
        const combinedSearchList = results.flatMap(result => result.filteredSearchList);

        setPreparedData({ alpha: combinedAlpha, beta: combinedBeta, searchList: combinedSearchList });
        setTitle(`${company}の業界での立ち位置`); // 初期タイトルを設定
      } catch (error) {
        console.error("データ準備中のエラー:", error);
      }
    };

    // 初期レンダリング時にもデータを準備
    prepareData();
  }, [visualType, topic, company]);


  useEffect(() => {
    const loadAuthorData = async () => {
      if (Array.isArray(company) && company.includes("株式会社熊谷組") || company === "株式会社熊谷組") {
        try {
          const promises = (topic || ["default_topic"]).map(async (topicId) => {
            const authorPath = `${process.env.PUBLIC_URL}/data/visualize_data/topic${topicId}/span=3/persona/kumagai_topic_author.json`;
            const response = await fetch(authorPath);
            if (!response.ok) {
              throw new Error(`著者データの読み込みに失敗: ${response.status}`);
            }
            const data = await response.json();
            
            // 年度とペルソナの対応マップ
            const yearToPersona = {
              "2024": "5",
              "2021": "4",
              "2019": "3",
              "2017": "2",
              "2015": "1"
            };
            
            // 各ペルソナのデータを整形
            const personaData = {};
            Object.entries(yearToPersona).forEach(([year, personaNum]) => {
              const yearData = data[year] || {};
              
              // 空のオブジェクトかどうかをチェック
              if (Object.keys(yearData).length === 0) {
                personaData[`persona_${personaNum}`] = {
                  authors: '出願者なし',
                  year: year
                };
              } else {
                // データがある場合は上位5件を取得
                const topAuthors = Object.entries(yearData)
                  .slice(0, 5)
                  .map(([author, count]) => `${author}(${count}件)`);
                
                personaData[`persona_${personaNum}`] = {
                  authors: topAuthors.join(', '),
                  year: year
                };
              }
            });
            
            return { topicId, data: personaData };
          });

          const results = await Promise.all(promises);
          const authorDataMap = {};
          
          results.forEach(({ topicId, data }) => {
            authorDataMap[topicId] = data;
          });
          
          setAuthorData(authorDataMap);
        } catch (error) {
          console.error("著者データの読み込みエラー:", error);
        }
      }
    };

    loadAuthorData();
  }, [company, topic]);


  useEffect(() => {
    if ((update || figData.length === 0) && preparedData) {
      const plotData = preparedData.searchList.map((k, j) => {
        const currentTopic = topic[j];
        const personaToYear = {

          "1": "2009",
          "2": "2012",
          "3": "2015",
          "4": "2018",
          "5": "2021"
        };

        const hoverTexts = ["1", "2", "3", "4", "5"].map((num) => {
          const yearText = `${personaToYear[num]}年`;
          const year = parseInt(yearText);  // 文字列を数値に変換
          if (k === "株式会社熊谷組" && authorData[currentTopic] && authorData[currentTopic][`persona_${num}`]) {
            const authorInfo = authorData[currentTopic][`persona_${num}`];
            return `(${year-3}~${year})<br>著者: ${authorInfo.authors}`;
          }
            return ` (${year-3}~${year})`;
        });

        return {
          x: preparedData.alpha[j],
          y: preparedData.beta[j],
          mode: "lines+markers+text",
          text: ["1", "2", "3", "4", "5"],
          textposition: "top left",
          hovertext: hoverTexts,
          hoverinfo: "text",
          hoverlabel: {
            align: 'left',
            bgcolor: 'white',
            bordercolor: 'gray',
            font: { size: 12 }
          },
          marker: {
            symbol: 'circle',
            color: colormap[IdtoTopic[topic[j]]],
            size: 5,
          },
          name: IdtoTopic[topic[j]],
        };
      });

  

      const plotAnnotations = preparedData.searchList.flatMap((k, j) =>
        Array(4).fill(0).map((_, i) => ({
          x: preparedData.alpha[j][i + 1],
          y: preparedData.beta[j][i + 1],
          xref: 'x',
          yref: 'y',
          axref: 'x',
          ayref: 'y',
          ax: preparedData.alpha[j][i],
          ay: preparedData.beta[j][i],
          arrowcolor:colormap[IdtoTopic[topic[j]]],
          arrowsize: 1.2,
          arrowwidth: 1.2,
          arrowhead: 5,
          showarrow: true,
        }))
      );

      setFigData(plotData);
      setAnnotations(plotAnnotations);

      if (onRendered) onRendered();
    }
  }, [update, preparedData, authorData, figData.length]);

  return (
    <div  style={{ width:'100vh' ,height: '100vh' }}>
      <Plot
        data={figData}
        layout={{
          plot_bgcolor: 'white',
          paper_bgcolor: 'white',
          annotations: annotations,
          title: {
            text: title,
            font: { size: 20, color: 'black' },
            x: 0.5,
            y: 0.95,
            xanchor: 'center',
          
          },
          annotations: [
            {
              x: 0.5,
              y: 1.8,
              text: '（業界を引っ張り伝統的な分野に取り組んでいる）',
              showarrow: false,
              font: { size: 9, color: 'gray' },
              xanchor: 'center',
              yanchor: 'middle',
            },
            {
              x: 1.5,
              y: 1.8,
              text: '（業界を引っ張り未知の分野に投資している）',
              showarrow: false,
              font: { size: 9, color: 'gray' },
              xanchor: 'center',
              yanchor: 'middle',
            },
            {
              x: 0.5,
              y: 0.2,
              text: '（独自路線を進み伝統的な分野に取り組んでいる）',
              showarrow: false,
              font: { size: 9, color: 'gray' },
              xanchor: 'center',
              yanchor: 'middle',
            },
            {
              x: 1.5,
              y: 0.2,
              text: '（独自路線を進み未知の分野に投資している）',
              showarrow: false,
              font: { size: 9, color: 'gray' },
              xanchor: 'center',
              yanchor: 'middle',
            },
          ],

         
          xaxis: {
            title : "新規性",
            range: [0.1, 1.9],
            linecolor: 'gray',
            linewidth: 1,
            gridcolor: 'lightgrey',
            gridwidth: 1,
            griddash: 'dot',
            tickmode:"array",
            tickvals:[0.1, 1, 1.9],
            ticktext:["低", "", "高"],
            zeroline: false,

          },
          yaxis: {
            title : "順応性",
            title_standoff:25,   // Y軸からの距離（見やすくするため）
            range: [0.1, 1.9],
            linecolor: 'gray',
            linewidth: 1,
            gridcolor: 'lightgrey',
            gridwidth: 1,
            griddash: 'dot',
            tickmode:"array",
            tickvals:[0.1, 1, 1.9],
            ticktext:["低", "", "高"],
            zeroline: false,

          },
          margin: { t: 25, b: 15, l: 15, r: 20 },
          showlegend: true,
          legend: {
            x: 1,
            y: 1,
            bgcolor: 'rgba(255,255,255,0.5)',
            bordercolor: 'gray',
            borderwidth: 1,
          },
          hoverdistance:50,
          hovermode: 'closest',
          hoverlabel: {
            namelength: -1  // 名前の長さ制限を解除
          },
        }}
        config={{ 
          responsive: true,
          displayModeBar: false  // ツールバーを非表示に
        }}
        style={{marginTop:"2vh", width: "100vh", height: "45vh" }}
      />
    </div>
  );
};

export default PlotPersonComp;
